@startuml
class Customer {
  +name : string
  +phoneNumber : string
}

class Table {
  +number : int
  +numberOfSeats : int
  +isSmoking : boolean
}

class Reservation {
  +day : date
  +time : time
  +numberOfPeople : int
}

class Waiter {
  +name : string
  +yearsOfService : int
}

class Bill {
  +totalAmount : float
}

class Dish {
  +name : string
  +unitPrice : float
}

class BillItem {
  +quantity : int
}

Customer "1" -- "*" Reservation : makes
Reservation "0..1" -- "*" Table : assigned to
Waiter "1" -- "*" Customer : serves
Waiter "1" -- "*" Table : serves
Customer "1" -- "0..1" Bill : pays
Bill "1" *-- "1..*" BillItem : made up of
BillItem "0..*" -- "1" Dish : includes
@enduml

